import React from 'react';
import { useQuiz } from '../context/QuizContext';

const AnswerReview = ({ onContinue, onGoBack }) => {
  const { state } = useQuiz();
  const { questions, answers } = state;

  const getAnswerStatus = (questionIndex) => {
    const userAnswer = answers[questionIndex];
    const correctAnswer = questions[questionIndex].correctAnswer;
    return {
      isCorrect: userAnswer === correctAnswer,
      userAnswer,
      correctAnswer
    };
  };

  const correctCount = answers.reduce((count, answer, index) => {
    return count + (answer === questions[index].correctAnswer ? 1 : 0);
  }, 0);

  return (
    <div className="card">
      <h2 style={{ 
        textAlign: 'center', 
        marginBottom: '30px',
        color: '#2d3748'
      }}>
        📋 Answer Review
      </h2>
      
      <div style={{
        marginBottom: '20px',
        padding: '15px',
        background: '#f7fafc',
        borderRadius: '10px',
        textAlign: 'center'
      }}>
        <div style={{ fontSize: '1.5rem', fontWeight: 'bold', color: '#667eea' }}>
          {correctCount} / {questions.length} Correct
        </div>
        <div style={{ fontSize: '1rem', color: '#718096', marginTop: '5px' }}>
          {Math.round((correctCount / questions.length) * 100)}% Accuracy
        </div>
      </div>

      <div style={{ marginBottom: '30px' }}>
        {questions.map((question, index) => {
          const status = getAnswerStatus(index);
          return (
            <div
              key={index}
              style={{
                marginBottom: '20px',
                padding: '15px',
                borderRadius: '10px',
                border: `2px solid ${status.isCorrect ? '#48bb78' : '#f56565'}`,
                background: status.isCorrect ? '#f0fff4' : '#fff5f5'
              }}
            >
              <div style={{
                display: 'flex',
                justifyContent: 'space-between',
                alignItems: 'flex-start',
                marginBottom: '10px'
              }}>
                <h4 style={{
                  margin: 0,
                  fontSize: '1rem',
                  color: '#2d3748',
                  flex: 1,
                  marginRight: '10px'
                }}>
                  Q{index + 1}: {question.question}
                </h4>
                <span style={{
                  fontSize: '1.5rem',
                  marginLeft: '10px'
                }}>
                  {status.isCorrect ? '✅' : '❌'}
                </span>
              </div>
              
              <div style={{ marginBottom: '8px' }}>
                <strong style={{ color: '#4a5568' }}>Your Answer: </strong>
                <span style={{
                  color: status.isCorrect ? '#2f855a' : '#c53030',
                  fontWeight: 'bold'
                }}>
                  {status.userAnswer !== null 
                    ? `${String.fromCharCode(65 + status.userAnswer)}. ${question.options[status.userAnswer]}`
                    : 'Not answered'
                  }
                </span>
              </div>
              
              {!status.isCorrect && (
                <div style={{ marginBottom: '8px' }}>
                  <strong style={{ color: '#4a5568' }}>Correct Answer: </strong>
                  <span style={{ color: '#2f855a', fontWeight: 'bold' }}>
                    {String.fromCharCode(65 + status.correctAnswer)}. {question.options[status.correctAnswer]}
                  </span>
                </div>
              )}
              
              <div style={{
                fontSize: '0.9rem',
                color: '#718096',
                fontStyle: 'italic'
              }}>
                💡 {question.explanation}
              </div>
            </div>
          );
        })}
      </div>

      <div style={{
        display: 'flex',
        justifyContent: 'space-between',
        gap: '15px'
      }}>
        <button
          onClick={onGoBack}
          style={{
            flex: 1,
            padding: '12px 20px',
            background: '#e2e8f0',
            color: '#4a5568',
            border: 'none',
            borderRadius: '8px',
            cursor: 'pointer',
            fontSize: '1rem',
            fontWeight: '600',
            transition: 'all 0.3s ease'
          }}
          onMouseOver={(e) => e.target.style.background = '#cbd5e0'}
          onMouseOut={(e) => e.target.style.background = '#e2e8f0'}
        >
          Review Questions
        </button>
        
        <button
          onClick={onContinue}
          style={{
            flex: 1,
            padding: '12px 20px',
            background: 'linear-gradient(135deg, #667eea 0%, #764ba2 100%)',
            color: 'white',
            border: 'none',
            borderRadius: '8px',
            cursor: 'pointer',
            fontSize: '1rem',
            fontWeight: '600',
            transition: 'all 0.3s ease'
          }}
          onMouseOver={(e) => e.target.style.transform = 'translateY(-2px)'}
          onMouseOut={(e) => e.target.style.transform = 'translateY(0)'}
        >
          Continue to Results
        </button>
      </div>
    </div>
  );
};

export default AnswerReview;
